mapper.select:
SELECT id, session_key, user_id, object_id, field_id, record_id,
       file_id, file_name, state, expires_at, idempotency_key,
       creator, create_time, updater, update_time, deleted
FROM public.nocode_biz_upload_session
WHERE user_id = #{userId}
AND object_id = #{objectId}
AND field_id = #{fieldId}
AND session_key = #{sessionKey}
AND idempotency_key = #{idempotencyKey}
AND state IN ('TEMPORARY','BINDING')
AND expires_at >= now()
AND deleted = 0
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE public.nocode_biz_upload_session
SET expires_at = #{expiresAt}, updater = #{actor}, update_time = now()
WHERE user_id = #{userId}
AND object_id = #{objectId}
AND left(session_key, 5) != 'task_'
AND state = 'TEMPORARY'
AND deleted = 0
AND expires_at >= now()
AND file_id IN
#{fid}
